/**
 * 报告 Hero 头图注册表(slug → 内联 data-URI)。
 *
 * 自包含:头图以 data-URI 内联进报告 HTML,不引外部 URL/CDN——与渲染器其余部分一致
 *(可离线打开 / 塞 iframe / 进中台)。只有被选中的那张进产物;未选则 Hero 回退为纯文字头。
 *
 * 加新主题头图:压成 JPEG → base64 data-URI,往 HEADER_ARTWORKS 加一条 slug;设计器下拉项在
 * field-editors/field-options.ts 的 HEADER_ART_OPTIONS 同步加标签(+ i18n)。本文件零 import,
 * 可逐字移植进 datav / zj 两个 fork。
 */
export const HEADER_ARTWORKS: Record<string, string> = {
  // 医疗环境主题
  medical:
    'data:image/jpeg;base64,',
  // 展业发展主题
  business:
    'data:image/jpeg;base64,',
  // 政务治理主题
  government:
    'data:image/jpeg;base64,',
  // 文旅城市主题
  tourism:
    'data:image/jpeg;base64,',
  // 生态环境主题
  ecology:
    'data:image/jpeg;base64,',
  // 高校主题 · 默认
  campus:
    'data:image/jpeg;base64,',
  // 高校主题 · 人才培养
  'campus-talent':
    'data:image/jpeg;base64,',
  // 高校主题 · 发展
  'campus-growth':
    'data:image/jpeg;base64,',
  // 高校主题 · 教学
  'campus-teaching':
    'data:image/jpeg;base64,',
  // 高校主题 · 数据治理
  'campus-data':
    'data:image/jpeg;base64,',
}

/** 解析 slug → data-URI;空 / 未注册返回 undefined(Hero 回退为纯文字头)。 */
export function resolveHeaderArt(slug?: string): string | undefined {
  if (!slug) return undefined
  return HEADER_ARTWORKS[slug]
}
